issue_context.body:
Observed on master.

When using d2i_AutoPrivateKey_ex with a non-NULL library context, default lib context appears to still be used for some operations.

In particular, this has been noticed for reading EC private keys from non-encrypted PKCS8 format for some curves.

Reproduced by loading 'null' provider into NULL context, and trying to read EC keys using another context that includes 'default' provider. Should work, but doesn't.

```
#include <openssl/provider.h>
#include <openssl/crypto.h>
#include <openssl/evp.h>
#include <openssl/err.h>

int main(int argc, char *argv[]) 
{
    OPENSSL_CTX *otherctx = NULL;
    OSSL_PROVIDER *defctxnull = NULL;
    EVP_PKEY *pkey256, *pkey384, *pkey521 = NULL;
    size_t buflen256, buflen384, buflen521;
    int ret;
    const unsigned char *bufp256, *bufp384, *bufp521;
    bufp256 = OPENSSL_hexstr2buf("3041020100301306072A8648CE3D020106082A8648CE3D03010704273025020101042065070A12B4FE4C0C1BD9828C891D6BBA376E8D62B07034B8875786B9DBCC6F0F", &buflen256);
   
    bufp384 = OPENSSL_hexstr2buf("304E020100301006072A8648CE3D020106052B8104002204373035020101043073E33A05F2B6996D0C337F159E10A9174C0A825771137AAC46A25E1CE0C7B2F82040C227C8BE027E9669E004CB890B42", &buflen384);

    bufp521 = OPENSSL_hexstr2buf("3060020100301006072A8648CE3D020106052B81040023044930470201010442005C013EAF1833C11DA2FAD152F4D276682D29EC2C79229D05174989446365FB2CEDFBAF704C2685A8FCC09502690BC13F3A158AE6C54E0C0356F2E8AAE2D81A3351", &buflen521);

    otherctx = OPENSSL_CTX_new();
    if (otherctx == NULL)
       goto end;
    
    /* Prevent anything from using the default library context */
    defctxnull = OSSL_PROVIDER_load(NULL, "null");

    /* For info print out providers available */
    ret = OSSL_PROVIDER_available(otherctx, "default");
    printf("default provider available (otherctx) : %d\n", ret);
    ret = OSSL_PROVIDER_available(otherctx, "null");
    printf("null provider available (otherctx) : %d\n", ret);
    ret = OSSL_PROVIDER_available(NULL, "default");
    printf("default provider available (NULL) : %d\n", ret);
    ret = OSSL_PROVIDER_available(NULL, "null");
    printf("null provider available (NULL) : %d\n", ret);

    pkey256 = d2i_AutoPrivateKey_ex(NULL, &bufp256, buflen256, otherctx, NULL);
    if (pkey256 == NULL)
        printf("Failed to read P256 key\n");
    else
        printf("Succesfully read P256 EC private key\n");

    pkey384 = d2i_AutoPrivateKey_ex(NULL, &bufp384, buflen384, otherctx, NULL);
    if (pkey384 == NULL)
        printf("Failed to read P384 key\n");
    else
        printf("Succesfully read P384 EC private key\n");

    pkey521 = d2i_AutoPrivateKey_ex(NULL, &bufp521, buflen521, otherctx, NULL);
    if (pkey521 == NULL)
        printf("Failed to read P521 key\n");
    else
        printf("Succesfully read P521 EC private key\n");

end:
    ERR_print_errors_fp(stderr);
    EVP_PKEY_free(pkey256);
    EVP_PKEY_free(pkey384);
    EVP_PKEY_free(pkey521);
    OPENSSL_CTX_free(otherctx);
    OSSL_PROVIDER_unload(defctxnull);
   
    return 1;
}
```
Output when running:
```
default provider available (otherctx) : 1
null provider available (otherctx) : 0
default provider available (NULL) : 0
null provider available (NULL) : 1
Succesfully read P256 EC private key
Failed to read P384 key
Failed to read P521 key
801B1F6D4D7F0000:error::digital envelope routines:(unknown function):fetch failed:../crypto/evp/evp_fetch.c:307:Default library context, Algorithm (AES-256-ECB), Properties ()
801B1F6D4D7F0000:error::digital envelope routines:(unknown function):fetch failed:../crypto/evp/evp_fetch.c:307:Default library context, Algorithm (AES-256-CTR), Properties ()
801B1F6D4D7F0000:error::random number generator:(unknown function):error initialising drbg:../crypto/rand/drbg_lib.c:404:
